const STOP_WORDS = new Set([
  'a','an','and','are','as','at','be','been','being','but','by','can','could','did','do','does','for','from',
  'had','has','have','how','i','if','in','into','is','it','its','me','my','of','on','or','our','should','so',
  'that','the','their','them','then','there','these','they','this','to','use','using','was','we','what','when',
  'where','which','who','why','will','with','would','you','your','cot','app','guide'
]);

function normalize(value: string) {
  return value.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, ' ').trim();
}

function tokens(value: string) {
  return [...new Set(normalize(value).split(/\s+/).filter((token) => token.length > 1 && !STOP_WORDS.has(token)))];
}

function hasAnyPermission(permissionCodes: string[], checks: string[]) {
  return checks.some((check) => check.endsWith('.')
    ? permissionCodes.some((code) => code.startsWith(check))
    : permissionCodes.includes(check));
}

function ministrySectionAllowed(section: CotGuideSection, permissionCodes: string[]) {
  if (section.audience !== 'ministry') return true;
  if (!permissionCodes.length) return false;
  const text = normalize(section.title + ' ' + section.path);

  const rules: Array<[RegExp, string[]]> = [
    [/giving|finance|refund|financial/, ['giving.', 'finance.']],
    [/prayer|pastoral|testimon|follow up|followup|counsell/, ['prayer.', 'testimonies.', 'pastoral.']],
    [/event|gathering|form|home banner|announcement|important update/, ['events.', 'announcements.']],
    [/sermon|devotional|library|bible|daily quote|scripture/, ['sermons.', 'bible.manage']],
    [/live|broadcast|stream/, ['streams.']],
    [/group/, ['groups.']],
    [/role|access|invite|leadership|title|badge|member|ownership/, ['roles.', 'members.', 'organization.leadership.manage', 'branches.update']],
    [/reel|video|creator studio|media|post|content studio/, ['posts.publish', 'media.upload', 'reels.create', 'videos.create', 'sermons.']],
    [/setting|expression setting|location|timezone/, ['branches.update', 'organization.update']],
  ];

  for (const [pattern, checks] of rules) {
    if (pattern.test(text)) return hasAnyPermission(permissionCodes, checks);
  }
  return true;
}

function sectionScore(section: CotGuideSection, query: string) {
  const queryTokens = tokens(query);
  if (!queryTokens.length) return Math.max(1, 100 - section.order);
  const title = normalize(section.title + ' ' + section.path);
  const body = normalize(section.content);
  let score = 0;
  for (const token of queryTokens) {
    if (title.includes(token)) score += 8;
    const matches = body.split(token).length - 1;
    score += Math.min(matches, 6);
  }
  const normalizedQuery = normalize(query);
  if (normalizedQuery.length > 3 && title.includes(normalizedQuery)) score += 24;
  return score;
}

export function retrieveCotGuideSections(options: {
  audiences: CotGuideAudience[];
  query: string;
  permissionCodes?: string[];
  limit?: number;
}) {
  const audienceSet = new Set(options.audiences);
  const permissionCodes = options.permissionCodes ?? [];
  const limit = Math.max(1, Math.min(options.limit ?? 7, 12));
  const eligible = COT_GUIDE_SECTIONS
    .filter((section) => audienceSet.has(section.audience))
    .filter((section) => ministrySectionAllowed(section, permissionCodes))
    .map((section) => ({ section, score: sectionScore(section, options.query) }))
    .sort((a, b) => b.score - a.score || a.section.order - b.section.order);

  const positive = eligible.filter((item) => item.score > 0).slice(0, limit);
  if (positive.length) return positive.map((item) => item.section);
  return eligible.slice(0, Math.min(limit, 4)).map((item) => item.section);
}

export function formatCotGuideContext(options: {
  audiences: CotGuideAudience[];
  query: string;
  permissionCodes?: string[];
  limit?: number;
}) {
  const sections = retrieveCotGuideSections(options);
  return sections.map((section) => [
    '[COT GUIDE]',
    'Audience: ' + section.audience,
    'Section: ' + section.path,
    section.content,
  ].join('\n')).join('\n\n');
}
